import{_ as a,o as d,c as e,a5 as r}from"./chunks/framework.D_J2JZBr.js";const u=JSON.parse('{"title":"考研与专业课准备","description":"从年度招生目录出发选择 IC 相关专业，核对上科大信息学院统考专业与考试科目。","frontmatter":{"title":"考研与专业课准备","description":"从年度招生目录出发选择 IC 相关专业，核对上科大信息学院统考专业与考试科目。"},"headers":[],"relativePath":"career/graduate-study/kaoyan.md","filePath":"career/graduate-study/kaoyan.md","lastUpdated":1795531638000}'),h={name:"career/graduate-study/kaoyan.md"};function i(o,t,n,l,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="考研与专业课准备" tabindex="-1">考研与专业课准备 <a class="header-anchor" href="#考研与专业课准备" aria-label="Permalink to &quot;考研与专业课准备&quot;">​</a></h1><p>考研规划先确认“招生单位 + 学院 + 专业代码 + 研究方向 + 培养项目”，再决定复习资料。同名专业在不同学院可能考不同专业课；同一导师的学术型和专业型入口也可能不同。不要先买一套题，再倒推报考目标。</p><h2 id="ic-相关专业通常看什么" tabindex="-1">IC 相关专业通常看什么 <a class="header-anchor" href="#ic-相关专业通常看什么" aria-label="Permalink to &quot;IC 相关专业通常看什么&quot;">​</a></h2><p>常见入口包括电子科学与技术、集成电路科学与工程、电子信息，以及与架构、EDA 相关的计算机专业。院校可能采用电路、模拟与数字电路、半导体物理与器件、信号与系统或计算机专业基础作为专业课，不存在全国统一的“IC 考研四科”。</p><p>可关注复旦大学、上海交通大学、上海科技大学、东南大学、西安电子科技大学、电子科技大学、浙江大学、中国科学技术大学及中国科学院相关培养单位等，按方向和目录逐一筛选；这不是院校排名，也不表示这些单位当年均以同一专业或科目招生。</p><p>数学一 / 数学二、英语一 / 英语二、统考 408 / 自命题的区别会直接影响备考，必须核对当年官方目录。专业代码相近也不能推定考试相同。</p><h2 id="上科大信息学院-2027-年入学统考目录" tabindex="-1">上科大信息学院：2027 年入学统考目录 <a class="header-anchor" href="#上科大信息学院-2027-年入学统考目录" aria-label="Permalink to &quot;上科大信息学院：2027 年入学统考目录&quot;">​</a></h2><p>以下依据学院 2026 年 10 月 8 日发布的 2027 年目录整理，仅适用于该年度。表中所有条目的公共科目均为 <strong>101 思想政治理论、201 英语一、301 数学一</strong>。</p><table tabindex="0"><thead><tr><th>专业代码与名称</th><th>目录中的方向 / 培养入口</th><th>第四单元科目</th></tr></thead><tbody><tr><td>080900 电子科学与技术</td><td>上科大本部、中科院联培研究院所</td><td>861 电路原理</td></tr><tr><td>081200 计算机科学与技术</td><td>上科大本部、中科院联培研究院所</td><td>408 计算机学科专业基础</td></tr><tr><td>081000 信息与通信工程</td><td>上科大本部、中科院联培研究院所</td><td>882 信号与系统</td></tr><tr><td>085400 电子信息</td><td>01 电子科学与技术方向</td><td>861 电路原理</td></tr><tr><td>085400 电子信息</td><td>02 计算机科学与技术方向</td><td>408 计算机学科专业基础</td></tr><tr><td>085400 电子信息</td><td>03 创芯学院联培专项</td><td>861 电路原理</td></tr><tr><td>085400 电子信息</td><td>04 集成电路工艺制造技术方向</td><td>861 电路原理</td></tr></tbody></table><p>目录将上述学术型硕士基本学制列为 3 年；专业型电子信息中的创芯学院联培专项列为 2 年，表内其他专业型方向列为 3 年。培养地点、导师、联合培养协议和毕业要求仍需阅读对应项目介绍，不能仅凭学制做决定。详见<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">培养项目</a>。</p><div class="warning custom-block"><p class="custom-block-title">计划数与考试范围会变化</p><p>学院通知中的人数是预计统考人数，并非最终录取承诺，实际计划以后续公告为准。本站不把推免通知中的专业代码、旧年度专业课或培养项目说明替代本年度统考目录。专业课范围请直接下载当年考试大纲与真题汇总核对。</p></div><h2 id="如何安排复习" tabindex="-1">如何安排复习 <a class="header-anchor" href="#如何安排复习" aria-label="Permalink to &quot;如何安排复习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>重点</th><th>检查办法</th></tr></thead><tbody><tr><td>了解目录与基础阶段</td><td>选定目标及备选，补齐数学、英语和专业课基础</td><td>能按概念解释题目，而不只是背答案</td></tr><tr><td>强化阶段</td><td>分专题训练，建立错题与薄弱点清单</td><td>定期闭卷重做，区分概念、计算与时间问题</td></tr><tr><td>真题阶段</td><td>按规定时长完成整套题，分析大纲覆盖</td><td>记录每科耗时、失分原因与改进</td></tr><tr><td>报名与冲刺阶段</td><td>核对报名、网上确认、考试安排</td><td>材料和截止日期单独列清单</td></tr><tr><td>初试后</td><td>查复试办法、整理项目、补基础表达</td><td>能解释自己的设计、实验与个人贡献</td></tr></tbody></table><p>861 的复习以当年大纲为依据，重点建立电路分析方法与完整推导习惯；408 的范围跨数据结构、组成原理、操作系统和计算机网络，应建立知识联系。882 则以当年信号与系统大纲为准。不要从科目名称反推指定教材，更不要购买来源不明的“内部真题”。</p><h2 id="复试准备与信息核查" tabindex="-1">复试准备与信息核查 <a class="header-anchor" href="#复试准备与信息核查" aria-label="Permalink to &quot;复试准备与信息核查&quot;">​</a></h2><p>复试可能涉及专业基础、项目介绍、英语及综合能力，具体形式和计分方式以当年办法为准。提前准备一页项目证据：问题、个人任务、方法、结果、失败及局限。不将课程成绩包装成科研成果，也不以背诵面经替代基础。</p><p>信息优先级为：学校研究生招生网 → 学院招生通知 → 官方大纲和项目介绍。论坛与经验帖可用于发现问题，但重要规则必须回到官网确认。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充考研复习经验，注明入学年份、专业代码和考试科目；不上传受限试题、个人成绩单或未经核实的录取预测。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2026/1008/c7339a1127895/page.htm" target="_blank" rel="noreferrer">信息学院 2027 年硕士研究生招生专业目录：统招</a></li><li><a href="https://sist.shanghaitech.edu.cn/2026/0930/c7340a1127808/page.htm" target="_blank" rel="noreferrer">信息学院 2027 年考试大纲及往年真题汇总</a></li><li><a href="https://yanzhao.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上海科技大学研究生招生网</a></li><li><a href="https://yz.chsi.com.cn/" target="_blank" rel="noreferrer">中国研究生招生信息网</a></li></ul>',20)])])}const b=a(h,[["render",i]]);export{u as __pageData,b as default};
